{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Naltrexone, the closest structural analogue and the tertiary-amine parent of the quaternary query, showed systemic bioavailability of only 5-6% after a single oral dose in healthy volunteers, directly supporting low oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Oral naltrexone bioavailability was approximately 5% in healthy male volunteers due to extensive first-pass hepatic metabolism, an affirmative low-F measurement for the closest analogue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Naltrexone is reported to have very poor oral bioavailability of about 5-10% in patients, reinforcing the low-F assignment for the close analogue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Morphine-6-glucuronide, a polar opioid derivative, has poor oral bioavailability, supporting the expectation that the permanently charged quaternary ammonium in the query impairs oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Nalmefene, a 6-methylene naltrexone analogue with a tertiary amine, had absolute oral bioavailability of 41% in humans; this is contradictory high evidence but less transferable because the query is a permanently charged quaternary ammonium.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C09"],
      "claim": "One naltrexone study reported 60% absolute oral bioavailability in volunteers, contradictory to low-F, but this is an outlier against multiple low estimates and does not account for the query's quaternary charge.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low: the query is methylnaltrexone, a quaternary ammonium analogue of naltrexone. The closest analogue naltrexone is repeatedly reported with low oral bioavailability (5-6%, ~5%, 5-10%) despite occasional higher estimates; the permanent positive charge further impairs membrane permeability and oral absorption. Higher-bioavailability analogues such as nalmefene and samidorphan are tertiary amines and less transferable.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for methylnaltrexone itself is present in the evidence set.",
    "Naltrexone bioavailability reports are conflicting, ranging from ~5% to 60%, creating uncertainty in extrapolation.",
    "The quantitative impact of the quaternary ammonium charge on oral absorption is inferred mechanistically rather than measured in the supplied records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

